const otx = $input.first().json;
const original = $('IOC Extraction').first().json;

const pulseInfo = otx.pulse_info || {};
const validation = otx.validation || [];
const reputation = otx.reputation ?? null;

return [{
  json: {
    ...original,
    otx: {
      reputation: reputation,
      pulse_count: pulseInfo.count ?? 0,
      sections: otx.sections || [],
      validation: validation,
      false_positive: otx.false_positive || []
    }
  }
}];

const input = $input.first().json;

// Convert any value to a searchable string
const rawText = JSON.stringify(input);

// ---------- IOC REGEX PATTERNS ----------

// IPv4 addresses
const ipRegex =
  /\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b/g;

// URLs
const urlRegex =
  /\bhttps?:\/\/[^\s"'<>]+/gi;

// Domains
const domainRegex =
  /\b(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}(?:\/[^\s"'<>]*)?/g;

// MD5
const md5Regex =
  /\b[a-fA-F0-9]{32}\b/g;

// SHA1
const sha1Regex =
  /\b[a-fA-F0-9]{40}\b/g;

// SHA256
const sha256Regex =
  /\b[a-fA-F0-9]{64}\b/g;

// Email addresses
const emailRegex =
  /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g;


// ---------- EXTRACTION FUNCTION ----------

function extract(regex) {
  return [...new Set(rawText.match(regex) || [])];
}


// ---------- EXTRACT IOCs ----------

const ipAddresses = extract(ipRegex);

const urls = extract(urlRegex);

const domains = extract(domainRegex);

const md5Hashes = extract(md5Regex);

const sha1Hashes = extract(sha1Regex);

const sha256Hashes = extract(sha256Regex);

const emails = extract(emailRegex);


// ---------- REMOVE DOMAINS THAT ARE ACTUALLY URL PARTS ----------

const cleanDomains = domains.filter(domain =>
  !domain.startsWith("http://") &&
  !domain.startsWith("https://")
);


// ---------- OUTPUT ----------

return [
  {
    json: {
      ...input,

      iocs: {
        ip_addresses: ipAddresses,
        urls: urls,
        domains: cleanDomains,
        hashes: {
          md5: md5Hashes,
          sha1: sha1Hashes,
          sha256: sha256Hashes
        },
        email_addresses: emails
      },

      ioc_summary: {
        ip_count: ipAddresses.length,
        url_count: urls.length,
        domain_count: cleanDomains.length,
        hash_count:
          md5Hashes.length +
          sha1Hashes.length +
          sha256Hashes.length,
        email_count: emails.length,

        has_ip: ipAddresses.length > 0,
        has_url: urls.length > 0,
        has_domain: cleanDomains.length > 0,
        has_hash:
          md5Hashes.length +
          sha1Hashes.length +
          sha256Hashes.length > 0,
        has_email: emails.length > 0
      }
    }
  }
];

const vt = $input.first().json;
const original = $('IOC Extraction').first().json;

const stats = vt.data?.attributes?.last_analysis_stats || {};

return [{
  json: {
    ...original,

    virustotal: {
      status: "success",
      ioc_type: "ip",
      ioc: original.iocs?.ip_addresses?.[0] || null,
      malicious: Number(stats.malicious || 0),
      suspicious: Number(stats.suspicious || 0),
      harmless: Number(stats.harmless || 0),
      undetected: Number(stats.undetected || 0),
      reputation: Number(vt.data?.attributes?.reputation || 0),
      tags: vt.data?.attributes?.tags || []
    }
  }
}];

const abuse = $input.first().json;
const original = $('IOC Extraction').first().json;

const data = abuse.data || {};

return [{
  json: {
    ...original,
    abuseipdb: {
      abuse_confidence_score: data.abuseConfidenceScore ?? 0,
      total_reports: data.totalReports ?? 0,
      distinct_users: data.numDistinctUsers ?? 0,
      country_code: data.countryCode ?? null,
      usage_type: data.usageType ?? null,
      isp: data.isp ?? null,
      domain: data.domain ?? null,
      is_public: data.isPublic ?? null,
is_whitelisted: data.isWhitelisted ?? null,
      last_reported_at: data.lastReportedAt ?? null
    }
  }
}];

const geo = $input.first().json;
const original = $('IOC Extraction').first().json;

return [{
  json: {
    ...original,
    geoip: {
      success: geo.success ?? false,
      country: geo.country ?? null,
      country_code: geo.country_code ?? null,
      region: geo.region ?? null,
      city: geo.city ?? null,
      latitude: geo.latitude ?? null,
      longitude: geo.longitude ?? null,
      isp: geo.connection?.isp ?? null,
      organization: geo.connection?.org ?? null
    }
  }
}];

const input = $input.first().json;
const data = input.data || {};
const attributes = data.attributes || {};

return [{
  json: {
    ...input,
    virustotal: {
      status: "success",
      ioc_type: "hash",
      ioc: data.id || "",
      sha256: attributes.sha256 || "",
      sha1: attributes.sha1 || "",
      md5: attributes.md5 || "",
      malicious: Number(attributes.last_analysis_stats?.malicious || 0),
      suspicious: Number(attributes.last_analysis_stats?.suspicious || 0),
      harmless: Number(attributes.last_analysis_stats?.harmless || 0),
      undetected: Number(attributes.last_analysis_stats?.undetected || 0),
      reputation: Number(attributes.reputation || 0),
      file_type: attributes.type_description || "",
      file_name: attributes.meaningful_name || ""
    }
  }
}];

const input = $input.first().json;

const url = input.iocs?.urls?.[0] || "";

const urlId = url
  ? Buffer.from(url)
      .toString("base64")
      .replace(/\+/g, "-")
      .replace(/\//g, "_")
      .replace(/=+$/, "")
  : "";

return [{
  json: {
    ...input,
    vt_url: url,
    vt_url_id: urlId
  }
}];

const input = $input.first().json;
const data = input.data || {};
const attributes = data.attributes || {};

return [{
  json: {
    ...input,
    virustotal_url: {
      status: "success",
      ioc_type: "url",
      ioc: input.vt_url || data.id || "",
      malicious: Number(attributes.last_analysis_stats?.malicious || 0),
      suspicious: Number(attributes.last_analysis_stats?.suspicious || 0),
      harmless: Number(attributes.last_analysis_stats?.harmless || 0),
      undetected: Number(attributes.last_analysis_stats?.undetected || 0),
      reputation: Number(attributes.reputation || 0),
      categories: attributes.categories || {}
    }
  }
}];

const input = $input.first().json;
const pulseInfo = input.pulse_info || {};

return [{
  json: {
    ...input,
    otx: {
      status: "success",
      ioc_type: "domain",
      domain: input.vt_url
        ? input.vt_url.replace(/^https?:\/\//, '').split('/')[0]
        : "",
      pulse_count: Number(pulseInfo.count || 0),
      pulses: pulseInfo.pulses || []
    }
  }
}];

const input = $input.first().json;

const failedAttempts = Number(input.failed_attempts) || 0;

const vtMalicious =
  Number(input.virustotal?.malicious) || 0;

const vtSuspicious =
  Number(input.virustotal?.suspicious) || 0;

const vtUrlMalicious =
  Number(input.virustotal_url?.malicious) || 0;

const vtUrlSuspicious =
  Number(input.virustotal_url?.suspicious) || 0;

const abuseScore =
  Number(input.abuseipdb?.abuse_confidence_score) || 0;

const abuseReports =
  Number(input.abuseipdb?.total_reports) || 0;

const otxPulses =
  Number(input.otx?.pulse_count) || 0;

const maliciousSources = [
  vtMalicious > 0,
  vtUrlMalicious > 0,
  abuseScore >= 50,
  otxPulses > 0
].filter(Boolean).length;

const evidence = {
  failed_attempts: failedAttempts,

  threat_intelligence: {
    virustotal_malicious: vtMalicious,
    virustotal_suspicious: vtSuspicious,

    virustotal_url_malicious: vtUrlMalicious,
    virustotal_url_suspicious: vtUrlSuspicious,

    abuse_confidence_score: abuseScore,
    abuse_reports: abuseReports,

    otx_pulse_count: otxPulses,

    malicious_source_count: maliciousSources
  },

  network_context: {
    is_public: input.abuseipdb?.is_public ?? null,
    is_whitelisted: input.abuseipdb?.is_whitelisted ?? null,
    geoip_success: input.geoip?.success ?? false
  },

  ioc_context: {
    ip_count: input.ioc_summary?.ip_count || 0,
    hash_count: input.ioc_summary?.hash_count || 0,
    url_count: input.ioc_summary?.url_count || 0,
    domain_count: input.ioc_summary?.domain_count || 0,
    has_ip: input.ioc_summary?.has_ip || false,
    has_hash: input.ioc_summary?.has_hash || false,
    has_url: input.ioc_summary?.has_url || false,
    has_domain: input.ioc_summary?.has_domain || false
  }
};

return [{
  json: {
    ...input,
    failed_attempts: failedAttempts,
    correlation: evidence
  }
}];

const input = $input.first().json;

const failedAttempts = Number(input.failed_attempts) || 0;

const maliciousSources =
  Number(input.correlation?.threat_intelligence?.malicious_source_count) || 0;

const successfulAfterBruteforce =
  input.successful_login_after_bruteforce === true;

const privilegedAccount =
  input.privileged_account === true;

const unusualCountry =
  input.unusual_country === true;

const outsideNormalHours =
  input.outside_normal_hours === true;

let score = 0;
const reasons = [];

if (maliciousSources > 0) {
  score += 30;
  reasons.push("Threat-intelligence evidence indicates malicious activity");
}

if (failedAttempts >= 50) {
  score += 20;
  reasons.push("50+ failed login attempts");
}

if (successfulAfterBruteforce) {
  score += 20;
  reasons.push("Successful login after brute-force activity");
}

if (privilegedAccount) {
  score += 15;
  reasons.push("Privileged account involved");
}

if (unusualCountry) {
  score += 10;
  reasons.push("Login from an unusual country");
}

if (outsideNormalHours) {
  score += 5;
  reasons.push("Activity occurred outside normal hours");
}

score = Math.max(0, Math.min(100, score));

let severity;

if (score >= 80) {
  severity = "CRITICAL";
} else if (score >= 60) {
  severity = "HIGH";
} else if (score >= 30) {
  severity = "MEDIUM";
} else {
  severity = "LOW";
}

return [{
  json: {
    ...input,
    severity: severity,
    risk_score: score,
    risk_reasons: JSON.stringify(reasons),
    risk: {
      score,
      severity,
      reasons
    }
  }
}];

const input = $input.first().json;

const risk = input.risk || {};
const correlation = input.correlation || {};
const ti = correlation.threat_intelligence || {};
const ioc = correlation.ioc_context || {};
const network = correlation.network_context || {};

return [{
  json: {
    ...input,

    investigation: {
      alert_id: input.alert_id || "",
      alert_type: input.alert_type || "",
      rule_id: input.rule_id || "",
      rule_level: input.rule_level ?? 0,
      rule_description: input.rule_description || "",

      agent: {
        name: input.agent_name || "",
        id: input.agent_id || "",
        hostname: input.hostname || ""
      },

      user: {
        username: input.username || "",
        privileged_account: input.privileged_account === true
      },

      network: {
        source_ip: input.source_ip || "",
        destination_ip: input.destination_ip || "",
        is_public: network.is_public ?? null,
        is_whitelisted: network.is_whitelisted ?? null,
        geoip_success: network.geoip_success ?? false
      },

      file: {
        path: input.file_path || "",
        process: input.process || ""
      },

      iocs: {
        has_ip: ioc.has_ip || false,
        has_hash: ioc.has_hash || false,
        has_url: ioc.has_url || false,
        has_domain: ioc.has_domain || false,
        ip_count: ioc.ip_count || 0,
        hash_count: ioc.hash_count || 0,
        url_count: ioc.url_count || 0,
        domain_count: ioc.domain_count || 0
      },

      risk: {
        score: risk.score ?? 0,
        severity: risk.severity ?? "UNKNOWN",
        reasons: risk.reasons || []
      },

      evidence: {
        failed_attempts: correlation.failed_attempts ?? 0,

        virustotal_malicious:
          ti.virustotal_malicious ?? 0,

        virustotal_suspicious:
          ti.virustotal_suspicious ?? 0,

        virustotal_url_malicious:
          ti.virustotal_url_malicious ?? 0,

        virustotal_url_suspicious:
          ti.virustotal_url_suspicious ?? 0,

        abuse_confidence_score:
          ti.abuse_confidence_score ?? 0,

        abuse_reports:
          ti.abuse_reports ?? 0,

        otx_pulse_count:
          ti.otx_pulse_count ?? 0,

        malicious_source_count:
          ti.malicious_source_count ?? 0
      },

      investigation_context:
        "Assess the available Wazuh alert, IOC, threat-intelligence, network, file, user, and risk evidence. Summarize why this alert requires investigation. Clearly distinguish confirmed evidence from unavailable information.",

      analyst_question:
        "What does the available evidence indicate, why was this risk score assigned, and what should the analyst verify next?"
    }
  }
}];

